#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}

    int howMany() const {
        return fish;
    }
};

int main() {
    Cat c1("{name}", {fish});
    cout << c1.howMany() << endl;
    return 0;
}
